mapper.select:
SELECT s.*, a.area_name, f.floor_name, (SELECT r.user_id FROM reservation r WHERE r.seat_id = s.id AND r.is_deleted = 0 AND r.status IN (0, 1) AND r.start_time <= NOW() AND r.end_time > NOW() ORDER BY r.start_time LIMIT 1) AS user_id, (SELECT u.username FROM reservation r JOIN sys_user u ON u.id = r.user_id AND u.is_deleted = 0 WHERE r.seat_id = s.id AND r.is_deleted = 0 AND r.status IN (0, 1) AND r.start_time <= NOW() AND r.end_time > NOW() ORDER BY r.start_time LIMIT 1) AS user_name FROM seat s LEFT JOIN area a ON a.id = s.area_id AND a.is_deleted = 0 LEFT JOIN floor f ON f.id = s.floor_id AND f.is_deleted = 0 WHERE s.is_deleted = 0
AND s.area_id = #{areaId}
ORDER BY f.floor_number, a.sort_order, s.seat_no

SELECT s.*, a.area_name, f.floor_name, (SELECT r.user_id FROM reservation r WHERE r.seat_id = s.id AND r.is_deleted = 0 AND r.status IN (0, 1) AND r.start_time <= NOW() AND r.end_time > NOW() ORDER BY r.start_time LIMIT 1) AS user_id, (SELECT u.username FROM reservation r JOIN sys_user u ON u.id = r.user_id AND u.is_deleted = 0 WHERE r.seat_id = s.id AND r.is_deleted = 0 AND r.status IN (0, 1) AND r.start_time <= NOW() AND r.end_time > NOW() ORDER BY r.start_time LIMIT 1) AS user_name FROM seat s LEFT JOIN area a ON a.id = s.area_id AND a.is_deleted = 0 LEFT JOIN floor f ON f.id = s.floor_id AND f.is_deleted = 0 WHERE s.floor_id = #{floorId} AND s.is_deleted = 0
AND s.area_id = #{areaId}
ORDER BY a.sort_order, s.seat_no
